css:
.ds-riso { --ds-cover-bg: var(--ds-paper); --ds-hand-ink: var(--ds-key); --ds-hand-fill: var(--ds-blue); --ds-hand-fill2: var(--ds-pink); --ds-hand-muted: var(--ds-paper-sunk); --ds-hand-ground: var(--ds-sheet); --ds-hand-stroke: 2; --ds-hand-cap: round; --ds-hand-bg: var(--ds-paper);
  --ds-tpl-edge: 2px solid var(--ds-key); --ds-tpl-radius: 0; --ds-tpl-rule: 1.5px dashed var(--ds-key); --ds-tpl-tile-shadow: var(--ds-shadow-hard); --ds-tag-radius: 0;
  --ds-slide-bg: var(--ds-sheet); --ds-slide-fg: var(--ds-key); --ds-slide-title-bg: var(--ds-blue); --ds-slide-title-fg: var(--ds-on-blue); --ds-slide-split-a: var(--ds-blue); --ds-slide-split-a-fg: var(--ds-on-blue); --ds-slide-split-b: var(--ds-pink); --ds-slide-split-b-fg: var(--ds-on-pink); --ds-hero-bg: var(--ds-paper); }
.ds-riso .ds-cover, .ds-riso .ri-cover, .ds-riso .ds-hand-art, .ds-riso .ds-motif-art { background-image: var(--ds-grain); background-size: 160px 160px; background-blend-mode: multiply; }
.ds-riso .ds-section h2, .ds-riso .ds-cover-name { font-variation-settings: "SOFT" 100, "WONK" 1; }
.ds-riso .ds-chip { border-width: 2px; border-color: var(--ds-key); font-family: var(--font-mono); font-weight: 400; }
.ds-riso .ds-cover-tag { font-style: italic; font-weight: 500; }
.ds-riso .ds-principle-n { font-family: var(--font-display); font-weight: 900; color: var(--ds-blue); }
.ds-riso .ri-paper { fill: var(--ds-paper); } .ds-riso .ri-sheet { fill: var(--ds-sheet); } .ds-riso .ri-manila { fill: var(--ds-manila); } .ds-riso .ri-proof { fill: var(--ds-sheet); stroke: var(--ds-line); stroke-width: 1.5; }
.ds-riso .ri-blue { fill: var(--ds-hand-fill, var(--ds-blue)); } .ds-riso .ri-pink { fill: var(--ds-hand-fill2, var(--ds-pink)); } .ds-riso .ri-yellow { fill: var(--ds-yellow); } .ds-riso .ri-key { fill: var(--ds-hand-ink, var(--ds-key)); }
.ds-riso .ri-mult { mix-blend-mode: multiply; } .dark .ds-riso .ri-mult { mix-blend-mode: normal; opacity: .9; }
.dark .ds-riso .h-plate { mix-blend-mode: normal; opacity: .9; }
.ds-riso .ri-key-line { fill: none; stroke: var(--ds-hand-ink, var(--ds-key)); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.ds-riso .ri-dots-pink circle { fill: var(--ds-hand-fill2, var(--ds-pink)); mix-blend-mode: multiply; }
.ds-riso .ri-mono { font-family: var(--font-mono); font-size: 11px; letter-spacing: .09em; fill: var(--ds-hand-ink, var(--ds-key)); } .ds-riso .ri-on-key { fill: var(--ds-sheet); } .ds-riso .ri-on-manila { fill: var(--ds-on-yellow); } .ds-riso .ri-navy { fill: var(--ds-on-yellow); } .ds-riso .ri-on-navy { fill: #F3ECDC; }
.ds-riso .ri-ovp-t { font-family: var(--font-display); font-size: 120px; font-weight: 900; letter-spacing: -.04em; font-variation-settings: "SOFT" 100, "WONK" 1; }
.ds-riso .ri-tag-h { font-family: var(--font-display); font-size: 34px; font-weight: 900; letter-spacing: -.02em; fill: var(--ds-key); font-variation-settings: "SOFT" 100, "WONK" 1; }
.ds-riso .ri-hole { fill: var(--ds-paper); stroke: var(--ds-key); stroke-width: 4; } .ds-riso .ri-string { fill: none; stroke: var(--ds-key); stroke-width: 2; stroke-dasharray: 4 4; }
.ds-riso .ri-tag-h { fill: var(--ds-on-yellow); } .ds-riso .ri-hole { fill: var(--ds-paper); stroke: var(--ds-on-yellow); } .dark .ds-riso .ri-tag-string, .ds-riso .ri-string { stroke: var(--ds-key); }
.ds-riso .ri-btn { font-family: var(--font-mono); font-size: 13px; letter-spacing: .06em; text-transform: uppercase; line-height: 20px; padding: 10px 16px; border: 2px solid var(--ds-key); background: var(--ds-sheet); color: var(--ds-key); box-shadow: var(--ds-shadow-hard); cursor: pointer; transition: transform 80ms ease-out, box-shadow 80ms ease-out; }
.ds-riso .ri-btn:hover { transform: translate(-2px, -2px); box-shadow: 8px 8px 0 0 var(--ds-key); } .dark .ds-riso .ri-btn:hover { box-shadow: 8px 8px 0 0 var(--ds-pink); }
.ds-riso .ri-btn:active { transform: translate(6px, 6px); box-shadow: 0 0 0 0 var(--ds-key); }
.ds-riso .ri-btn:focus-visible { outline: 3px solid var(--ds-pink); outline-offset: 3px; }
.ds-riso .ri-btn-blue { background: var(--ds-blue); color: var(--ds-on-blue); } .ds-riso .ri-btn-pink { background: var(--ds-pink); color: var(--ds-on-pink); }
.ds-riso .ri-tag { display: inline-flex; align-items: center; gap: 6px; padding: 3px 8px; border: 2px solid var(--ds-key); font-family: var(--font-mono); font-size: 11px; letter-spacing: .09em; text-transform: uppercase; line-height: 16px; background: var(--ds-sheet); color: var(--ds-key); }
.ds-riso .ri-tag-blue { background: var(--ds-blue); color: var(--ds-on-blue); } .ds-riso .ri-tag-pink { background: var(--ds-pink); color: var(--ds-on-pink); } .ds-riso .ri-tag-yellow { background: var(--ds-yellow); color: var(--ds-on-yellow); } .ds-riso .ri-tag-positive { background: var(--ds-positive-soft); color: var(--ds-positive); }
.ds-riso .ri-door { display: grid; grid-template-columns: auto 1fr; gap: 14px; align-items: center; min-width: 180px; }
.ds-riso .ri-door-n { display: inline-block; padding: 6px 12px 2px; min-width: 2.1em; text-align: center; position: relative; }
.ds-riso .ri-door-blue .ri-door-n { background: var(--ds-blue); color: var(--ds-on-blue); } .ds-riso .ri-door-pink .ri-door-n { background: var(--ds-pink); color: var(--ds-on-pink); } .ds-riso .ri-door-yellow .ri-door-n { background: var(--ds-yellow); color: var(--ds-on-yellow); }
.ds-riso .ri-door div { display: grid; gap: 2px; } .ds-riso .ri-door-s { font-size: 14px; color: var(--ds-key-2); }
.ds-riso .ds-stats { gap: 28px; }
.ds-riso .ri-callout { position: relative; padding: 16px 18px 16px; border: 1.5px dashed var(--ds-key); background: var(--ds-sheet); line-height: 1.5; font-size: 16px; margin-top: 8px; } .ds-riso .ri-callout strong { font-weight: 900; }
.ds-riso .ri-callout-blue { background: var(--ds-blue-soft); } .ds-riso .ri-callout-positive { background: var(--ds-positive-soft); } .ds-riso .ri-callout-negative { background: var(--ds-negative-soft); }
.ds-riso .ri-folio { position: absolute; top: -12px; right: 16px; background: var(--ds-key); color: var(--ds-sheet); font-family: var(--font-mono); font-size: 11px; letter-spacing: .09em; text-transform: uppercase; padding: 3px 9px; line-height: 16px; }
.ds-riso .ri-folio-br { top: auto; bottom: 10px; right: 14px; }
.ds-riso .ri-hl { font-weight: 700; background: linear-gradient(transparent 58%, var(--ds-yellow) 58% 92%, transparent 92%); } .dark .ds-riso .ri-hl { background: var(--ds-yellow); color: var(--ds-on-yellow); padding: 0 .12em; }
.ds-riso .ri-card { position: relative; background: var(--ds-sheet); border: 2px solid var(--ds-key); padding: 26px 26px 22px; max-width: 460px; box-shadow: var(--ds-shadow-hard-lg); transform: rotate(-.6deg); display: grid; gap: 12px; justify-items: start; transition: transform 160ms ease-out; }
.ds-riso .ri-card:hover { transform: rotate(0deg) translateY(-4px); } .ds-riso .ri-card-b { transform: rotate(.7deg); }
.ds-riso .ri-card h3 { margin: 0; } .ds-riso .ri-card p { margin: 0; } .ds-riso .ri-card-body { line-height: 1.5; }
.ds-riso .ri-sample { background: var(--ds-paper); border-top: 2px solid var(--ds-key); border-bottom: 2px solid var(--ds-key); overflow: hidden; }
.ds-riso .ri-runhead { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 8px 16px; padding: 14px 20px; border-bottom: 2px solid var(--ds-key); }
.ds-riso .ri-cover { display: grid; gap: 24px; padding: 32px 20px 40px; background-image: var(--ds-grain); }
.ds-riso .ri-cover-words { min-width: 0; }
.ds-riso .ri-kicker { display: inline-flex; align-items: center; gap: 10px; margin: 0 0 18px; }
.ds-riso .ri-pip { display: inline-block; width: 12px; height: 12px; border-radius: 50%; } .ds-riso .ri-pip-blue { background: var(--ds-blue); }
.ds-riso .ri-h1 { margin: 0; } .ds-riso .ri-h1-l1 { display: block; margin-bottom: .1em; }
.ds-riso .ri-h1-l2 { display: block; font-family: var(--font-display); font-weight: 900; font-size: clamp(64px, 11vw, 150px); line-height: .84; letter-spacing: -.045em; color: var(--ds-blue); font-variation-settings: "SOFT" 100, "WONK" 1; padding-bottom: .08em; }
.ds-riso .ri-ovp { position: relative; isolation: isolate; display: inline-block; }
.ds-riso .ri-ovp::before, .ds-riso .ri-ovp::after { content: attr(data-text); position: absolute; inset: 0; pointer-events: none; mix-blend-mode: multiply; z-index: -1; }
.ds-riso .ri-ovp::before { color: var(--ds-pink); transform: translate(.045em, .03em); } .ds-riso .ri-ovp::after { color: var(--ds-yellow); transform: translate(-.035em, .05em); }
.dark .ds-riso .ri-ovp::before, .dark .ds-riso .ri-ovp::after { mix-blend-mode: screen; }
.ds-riso .ri-dek { margin: 24px 0 0; max-width: 30ch; }
.ds-riso .ri-imprint { display: flex; flex-wrap: wrap; gap: 8px 22px; margin-top: 24px; color: var(--ds-key-2); }
.ds-riso .ri-turn { display: inline-block; margin-top: 28px; border-bottom: 2px solid var(--ds-key); padding-bottom: 4px; }
.ds-riso .ri-cover-art { position: relative; } .ds-riso .ri-cover-svg { display: block; width: 100%; height: auto; }
.ds-riso .ri-badge { position: absolute; right: 8px; top: 8px; width: 108px; height: 108px; border-radius: 50%; background: var(--ds-pink); color: var(--ds-on-pink); display: grid; place-items: center; text-align: center; transform: rotate(12deg); font-family: var(--font-mono); font-size: 10.5px; line-height: 1.3; text-transform: uppercase; letter-spacing: .06em; padding: 12px; }
.ds-riso .ri-badge b { display: block; font-family: var(--font-display); font-size: 26px; font-weight: 500; font-style: italic; letter-spacing: 0; text-transform: none; }
.ds-riso .ri-ticker { overflow: hidden; background: var(--ds-yellow); color: var(--ds-on-yellow); border-top: 2px solid var(--ds-key); border-bottom: 2px solid var(--ds-key); padding: 10px 0; }
.ds-riso .ri-ticker-track { display: flex; width: max-content; font-family: var(--font-mono); font-size: 13px; letter-spacing: .09em; text-transform: uppercase; }
.ds-riso .ri-ticker-track span { padding: 0 18px; white-space: nowrap; } .ds-riso .ri-ticker-track i { font-style: normal; color: var(--ds-pink); mix-blend-mode: multiply; margin: 0 10px; }
.ds-riso .ri-scene { display: grid; gap: 32px; padding: 40px 20px 56px; }
.ds-riso .ri-steps { display: grid; gap: 36px; align-content: start; justify-items: start; }
.ds-riso .ri-tagwrap { position: relative; transform: rotate(-2deg); margin-left: 24px; }
.ds-riso .ri-tag-card { position: relative; background: var(--ds-manila); color: var(--ds-on-yellow); clip-path: polygon(34px 0, 100% 0, 100% 100%, 34px 100%, 0 calc(100% - 34px), 0 34px); padding: 24px 24px 36px 62px; max-width: 420px; }
.ds-riso .ri-tag-card::before { content: ""; position: absolute; left: 18px; top: 50%; width: 20px; height: 20px; margin-top: -10px; border-radius: 50%; background: var(--ds-paper); box-shadow: 0 0 0 5px var(--ds-on-yellow) inset; }
.ds-riso .ri-tag-card h3 { margin: 0 0 10px; font-variation-settings: "SOFT" 100, "WONK" 1; }
.ds-riso .ri-dl { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 4px 14px; } .ds-riso .ri-dl dt { font-family: var(--font-mono); font-size: 11px; letter-spacing: .08em; text-transform: uppercase; padding-top: 3px; } .ds-riso .ri-dl dd { margin: 0; font-family: var(--font-mono); font-size: 14px; line-height: 1.35; }
.ds-riso .ri-stage { align-self: start; }
.ds-riso .ri-proof { background: var(--ds-sheet); border: 1.5px solid var(--ds-line); box-shadow: 14px 16px 0 0 var(--ds-paper-sunk); transform: rotate(-.8deg); padding: 20px; }
.ds-riso .ri-fig { margin: 12px 0 0; color: var(--ds-key-2); }
.ds-riso .ds-tpl-tag.is-idle { background: var(--ds-paper-sunk); }
.ds-riso .ds-tpl-brand, .ds-riso .ds-tpl-slide-h, .ds-riso .ds-tpl-hero-h, .ds-riso .ds-tpl-ed-h, .ds-riso .ds-tpl-dropcap { font-variation-settings: "SOFT" 100, "WONK" 1; }
.ds-riso .ds-tpl-slide-big { font-variation-settings: "SOFT" 100, "WONK" 1; }
.ds-riso .ds-tpl-step { transform: rotate(-.4deg); box-shadow: var(--ds-shadow-hard); } .ds-riso .ds-tpl-step + .ds-tpl-step { transform: rotate(.5deg); }
.ds-riso .ds-tpl-kpi { box-shadow: var(--ds-shadow-hard); }
@container (min-width: 760px) {
  .ds-riso .ri-cover { grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr); align-items: center; gap: 2vw; padding: 48px 40px 64px; }
  .ds-riso .ri-runhead { padding: 14px 40px; }
  .ds-riso .ri-scene { grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr); padding: 56px 40px 72px; }
}
